121	    /// let chunks: Vec<_> = [1, 2, 3, 4, 5].par_chunks(2).collect();
122	    /// assert_eq!(chunks, vec![&[1, 2][..], &[3, 4], &[5]]);
123	    /// ```
124	    #[track_caller]
125	    fn par_chunks(&self, chunk_size: usize) -> Chunks<'_, T> {
126	        assert!(chunk_size != 0, "chunk_size must not be zero");
