194	    /// it means the predicate is called on `slice[0]` and `slice[1]`
195	    /// then on `slice[1]` and `slice[2]` and so on.
196	    ///
197	    /// # Examples
198	    ///
199	    /// ```
200	    /// use rayon::prelude::*;
201	    /// let chunks: Vec<_> = [1, 2, 2, 3, 3, 3].par_chunk_by(|&x, &y| x == y).collect();
