1	//! Parallel iterator types for [ranges],
2	//! the type for values created by `a..b` expressions
3	//!
4	//! You will rarely need to interact with this module directly unless you have
5	//! need to name one of the iterator types.
6	//!
7	//! ```
8	//! use rayon::prelude::*;
9	//!
10	//! let r = (0..100u64).into_par_iter()
11	//!                    .sum();
12	//!
13	//! // compare result with sequential calculation
14	//! assert_eq!((0..100).sum::<u64>(), r);
15	//! ```
16	//!
17	//! [ranges]: std::ops::Range
18	
19	use crate::iter::plumbing::*;
20	use crate::iter::*;
21	use std::ops::Range;
22	
23	/// Parallel iterator over a range, implemented for all integer types and `char`.
24	///
25	/// **Note:** The `zip` operation requires `IndexedParallelIterator`
26	/// which is not implemented for `u64`, `i64`, `u128`, or `i128`.
27	///
28	/// ```
29	/// use rayon::prelude::*;
30	///
31	/// let p = (0..25usize).into_par_iter()
32	///                   .zip(0..25usize)
33	///                   .filter(|&(x, y)| x % 5 == 0 || y % 5 == 0)
34	///                   .map(|(x, y)| x * y)
35	///                   .sum::<usize>();
36	///
37	/// let s = (0..25usize).zip(0..25)
38	///                   .filter(|&(x, y)| x % 5 == 0 || y % 5 == 0)
39	///                   .map(|(x, y)| x * y)
40	///                   .sum();
41	///
42	/// assert_eq!(p, s);
43	/// ```
44	#[derive(Debug, Clone)]
45	pub struct Iter<T> {
46	    range: Range<T>,
47	}
48	
49	/// Implemented for ranges of all primitive integer types and `char`.
50	impl<T> IntoParallelIterator for Range<T>
51	where
52	    Iter<T>: ParallelIterator,
53	{
54	    type Item = <Iter<T> as ParallelIterator>::Item;
55	    type Iter = Iter<T>;
56	
57	    fn into_par_iter(self) -> Self::Iter {
58	        Iter { range: self }
59	    }
60	}
61	
62	struct IterProducer<T> {
63	    range: Range<T>,
64	}
65	
66	impl<T> IntoIterator for IterProducer<T>
67	where
68	    Range<T>: Iterator,
69	{
70	    type Item = <Range<T> as Iterator>::Item;
71	    type IntoIter = Range<T>;
72	
73	    fn into_iter(self) -> Self::IntoIter {
74	        self.range
75	    }
76	}
77	
78	// These traits help drive integer type inference. Without them, an unknown `{integer}` type only
79	// has constraints on `Iter<{integer}>`, which will probably give up and use `i32`. By adding
80	// these traits on the item type, the compiler can see a more direct constraint to infer like
81	// `{integer}: RangeInteger`, which works better. See `test_issue_833` for an example.
82	
83	/// Implementation details of `ParallelIterator for Iter<Self>`
84	trait RangeInteger: Sized + Send {
85	    fn drive_unindexed<C>(iter: Iter<Self>, consumer: C) -> C::Result
86	    where
87	        C: UnindexedConsumer<Self>;
88	
89	    fn opt_len(iter: &Iter<Self>) -> Option<usize>;
90	}
91	
92	/// Implementation details of `IndexedParallelIterator for Iter<Self>`
93	trait IndexedRangeInteger: RangeInteger {
94	    fn drive<C>(iter: Iter<Self>, consumer: C) -> C::Result
95	    where
96	        C: Consumer<Self>;
97	
98	    fn len(iter: &Iter<Self>) -> usize;
99	
100	    fn with_producer<CB>(iter: Iter<Self>, callback: CB) -> CB::Output
101	    where
102	        CB: ProducerCallback<Self>;
103	}
104	
105	impl<T: RangeInteger> ParallelIterator for Iter<T> {
106	    type Item = T;
107	
108	    fn drive_unindexed<C>(self, consumer: C) -> C::Result
109	    where
110	        C: UnindexedConsumer<T>,
111	    {
112	        T::drive_unindexed(self, consumer)
113	    }
114	
115	    #[inline]
116	    fn opt_len(&self) -> Option<usize> {
117	        T::opt_len(self)
118	    }
119	}
120	
121	impl<T: IndexedRangeInteger> IndexedParallelIterator for Iter<T> {
122	    fn drive<C>(self, consumer: C) -> C::Result
123	    where
124	        C: Consumer<T>,
125	    {
126	        T::drive(self, consumer)
127	    }
128	
129	    #[inline]
130	    fn len(&self) -> usize {
131	        T::len(self)
132	    }
133	
134	    fn with_producer<CB>(self, callback: CB) -> CB::Output
135	    where
136	        CB: ProducerCallback<T>,
137	    {
138	        T::with_producer(self, callback)
139	    }
140	}
141	
142	macro_rules! indexed_range_impl {
143	    ( $t:ty ) => {
144	        impl RangeInteger for $t {
145	            fn drive_unindexed<C>(iter: Iter<$t>, consumer: C) -> C::Result
146	            where
147	                C: UnindexedConsumer<$t>,
148	            {
149	                bridge(iter, consumer)
150	            }
151	
152	            fn opt_len(iter: &Iter<$t>) -> Option<usize> {
153	                Some(iter.range.len())
154	            }
155	        }
156	
157	        impl IndexedRangeInteger for $t {
158	            fn drive<C>(iter: Iter<$t>, consumer: C) -> C::Result
159	            where
160	                C: Consumer<$t>,
161	            {
162	                bridge(iter, consumer)
163	            }
164	
165	            fn len(iter: &Iter<$t>) -> usize {
166	                iter.range.len()
167	            }
168	
169	            fn with_producer<CB>(iter: Iter<$t>, callback: CB) -> CB::Output
170	            where
171	                CB: ProducerCallback<$t>,
172	            {
173	                callback.callback(IterProducer { range: iter.range })
174	            }
175	        }
176	
177	        impl Producer for IterProducer<$t> {
178	            type Item = <Range<$t> as Iterator>::Item;
179	            type IntoIter = Range<$t>;
180	            fn into_iter(self) -> Self::IntoIter {
181	                self.range
182	            }
183	
184	            fn split_at(self, index: usize) -> (Self, Self) {
185	                assert!(index <= self.range.len());
186	                // For signed $t, the length and requested index could be greater than $t::MAX, and
187	                // then `index as $t` could wrap to negative, so wrapping_add is necessary.
188	                let mid = self.range.start.wrapping_add(index as $t);
189	                let left = self.range.start..mid;
190	                let right = mid..self.range.end;
191	                (IterProducer { range: left }, IterProducer { range: right })
192	            }
193	        }
194	    };
195	}
196	
197	trait UnindexedRangeLen<L> {
198	    fn unindexed_len(&self) -> L;
199	}
200

